#!/usr/bin/env bash
# Bundle item 203 law30_summary_31 (thread "Site: Add Law and Justice committee", 23 Nov 2569, asked by the 3x-daily routine)
# Senate list fetched 23 Nov 2569 11:55 UTC; every document used is Rpublic=1.
#   Main 30 (Wed 18 Nov 2569, MID 353872): summary "สรุปข่าว 30-2569.pdf" (ref 11236372) + "ระเบียบวาระและเอกสารประกอบ.pdf"
#     (ref 11236379) -> links; the card's agenda text becomes an easy-read summary written from the Senate's summary
#     (chair พลตำรวจโท บุญจันทร์ นวลสาย; two complaints written as allegations with no finding and no names).
#   Main 31 (Wed 25 Nov 2569, MID 354091): new meeting, date only (no documents yet) -> upcoming date card, all-day calendar file.
# Surgical, JSON-level edits of the live lines only (same engine as items 69/119/148/190): law/2569/index.html DATA (30 and 31 only),
#   EZ.cal (+31), SHARE_V, UPDATED; meetings.json; i18n-en.json (missing keys only); share pages/cards of 30 and 31, QR of 31.
#   Live "media" kept (meeting 30 pre video); audio/ untouched (the listen voice for meeting 30 is re-recorded by the routine).
# SELF-CONTAINED (shared folder over its cap): payload embedded below as base64 tar.gz. Idempotent; no git, no network.
set -euo pipefail
: "${HUB:?HUB not set}"
TMPP=$(mktemp -d)
trap 'rm -rf "$TMPP"' EXIT
sed -n '/^__PAYLOAD_BELOW__$/,$p' "$0" | tail -n +2 | base64 -d | tar -xz -C "$TMPP"
PAY="$TMPP/pay"
M="$HUB/law/2569"
for f in index.html meetings.json i18n-en.json; do
  test -f "$M/$f" || { echo "203_law30_summary_31: $M/$f missing" >&2; exit 1; }; done
(cd "$PAY/files" && find . -type f) | while read -r f; do
  mkdir -p "$(dirname "$M/$f")"; cmp -s "$PAY/files/$f" "$M/$f" || cp -f "$PAY/files/$f" "$M/$f"; done
python3 - "$M" "$PAY/payload.json" <<'PY'
import json, os, re, sys
M, PAYF = sys.argv[1], sys.argv[2]
P = json.load(open(PAYF, encoding='utf-8'))
dec = json.JSONDecoder()
SERS = (lambda a: json.dumps(a, ensure_ascii=False), lambda a: json.dumps(a, ensure_ascii=False, separators=(',', ':')))
def one(L, pre):
    idx = [i for i, l in enumerate(L) if l.startswith(pre)]
    assert len(idx) == 1, f'203: {pre} not found once'; return idx[0]
def jline(L, pre):
    i = one(L, pre); body = L[i][len(pre):]; val, end = dec.raw_decode(body); tail = body[end:]
    for ser in SERS:
        if pre + ser(val) + tail == L[i]: return i, val, tail, ser
    raise SystemExit(f'203: {pre} does not round-trip; not touching it')
def merge(arr, new, keep_media=True):
    by = {(m['n'], m['date']): k for k, m in enumerate(arr)}
    for key, m in new.items():
        n, d = key.split('|'); key = (int(n), d); m = dict(m)
        if key in by:
            old = arr[by[key]]
            if keep_media and 'media' in old: m['media'] = old['media']      # media belongs to the video items
            arr[by[key]] = m
        else:
            arr.append(m)
    arr.sort(key=lambda m: (m['date'], m['n']), reverse=True); return arr
def set_share(L, sv):
    i = one(L, 'const SHARE_P=')
    for n, h in sv.items():
        pat = r'"%s": ?"[0-9a-f]{8}"' % re.escape(n)
        if re.search(pat, L[i]):
            L[i] = re.sub(pat, lambda mm: mm.group(0)[:-10] + '"' + h + '"', L[i], count=1)
        else:                                   # new meeting: first key of SHARE_V, newest first as the build writes it
            L[i], k = re.subn(r'SHARE_V=\{', lambda mm: 'SHARE_V={"%s": "%s", ' % (n, h), L[i], count=1)
            assert k == 1, '203: SHARE_V not found'
    j = L[i]
    m = re.search(r'SHARE_QR=\[([^\]]*)\]', j)
    if m:
        qr = [x.strip() for x in m.group(1).split(',') if x.strip()]
        add = [('"%s"' % n if qr and qr[0].startswith('"') else n) for n in sv if ('"%s"' % n) not in qr and n not in qr]
        if add:
            L[i] = j[:m.start(1)] + ', '.join(add + qr) + j[m.end(1):]
def set_updated(L, new):
    i = one(L, 'const UPDATED=')
    cur = L[i][len('const UPDATED="'):len('const UPDATED="') + 10]
    if cur < new: L[i] = L[i].replace(cur, new, 1)
def write(path, L, orig):
    t = '\n'.join(L)
    if t != orig: open(path, 'w', encoding='utf-8').write(t); print('203 changed', os.path.basename(path))
def jfile(path, new):
    raw = open(path, encoding='utf-8').read(); ms = json.loads(raw)
    fmt = [k for k in (dict(indent=1), dict(), dict(separators=(',', ':'))) if json.dumps(ms, ensure_ascii=False, **k) == raw.rstrip('\n')]
    assert fmt, '203: %s does not round-trip' % path
    out = json.dumps(merge(ms, new), ensure_ascii=False, **fmt[0]) + ('\n' if raw.endswith('\n') else '')
    if out != raw: open(path, 'w', encoding='utf-8').write(out); print('203 changed', os.path.basename(path))

# main page
p = os.path.join(M, 'index.html'); orig = open(p, encoding='utf-8').read(); L = orig.split('\n')
if P['main']['data']:
    i, arr, tail, ser = jline(L, 'const DATA='); L[i] = 'const DATA=' + ser(merge(arr, P['main']['data'])) + tail
i, subs, tail, ser = jline(L, 'const SUBS=')
for s in subs:
    u = P['subs_line'].get(s['key'])
    if u:
        s['fetched'] = max(s.get('fetched') or '', u['fetched'])
        s['meetings'] = merge(s['meetings'], u['meetings'], keep_media=False)
L[i] = 'const SUBS=' + ser(subs) + tail
if P['main']['data']:
    i, ez, tail, ser = jline(L, 'const EZ='); ez['cal'] = P['main']['cal']; L[i] = 'const EZ=' + ser(ez) + tail
set_share(L, P['main']['share_v'])
if P['main']['data']: set_updated(L, P['updated'])
write(p, L, orig)
if P['main']['json']: jfile(os.path.join(M, 'meetings.json'), P['main']['json'])

# subcommittee pages
for k, S in P['sub'].items():
    p = os.path.join(M, 'sub-%s.html' % k); orig = open(p, encoding='utf-8').read(); L = orig.split('\n')
    i, arr, tail, ser = jline(L, 'const DATA='); L[i] = 'const DATA=' + ser(merge(arr, S['data'])) + tail
    i, tl, tail, ser = jline(L, 'const TL=')
    tl = [x for x in tl if x not in S['tl_drop']]
    for x in S['tl_add']:
        if x not in tl:
            at = next((q for q, y in enumerate(tl) if y[0] > x[0]), len(tl)); tl.insert(at, x)
    L[i] = 'const TL=' + ser(tl) + tail
    i, ez, tail, ser = jline(L, 'const EZ='); ez['cal'] = S['cal']; L[i] = 'const EZ=' + ser(ez) + tail
    set_share(L, S['share_v'])
    set_updated(L, S['updated'])
    write(p, L, orig)
    jfile(os.path.join(M, 'sub-%s.json' % k), S['json'])

# English
ip = os.path.join(M, 'i18n-en.json'); raw = open(ip, encoding='utf-8').read(); d = json.loads(raw)
assert json.dumps(d, ensure_ascii=False, separators=(',', ':')) == raw, '203: i18n-en.json format changed; not touching it'
add = {a: b for a, b in P['en'].items() if a not in d}
if add:
    d.update(add); open(ip, 'w', encoding='utf-8').write(json.dumps(d, ensure_ascii=False, separators=(',', ':'))); print('203 i18n +%d' % len(add))
PY
python3 - "$M" <<'PY'
import json, os, sys
M = sys.argv[1]
def get(f, n, d):
    r = [m for m in json.load(open(os.path.join(M, f), encoding='utf-8')) if (m['n'], m['date']) == (n, d)]
    assert len(r) == 1, '203: %s %s %s not found once' % (f, n, d); return r[0]
def has(m, ref): return any(ref in x.get('url', '') for x in m['docs'])
m = get('meetings.json', 30, '2026-11-18')
assert has(m, '11236372') and has(m, '11236379') and has(m, '11215972') and not m.get('agenda_only') and not m.get('upcoming') and m.get('chair') == 'พลตำรวจโท บุญจันทร์ นวลสาย', '203: main 30'
assert (m.get('media') or {}).get('video'), '203: main 30 lost its live video'
m = get('meetings.json', 31, '2026-11-25'); assert m.get('upcoming'), '203: main 31'
assert os.path.isfile(os.path.join(M, 'cal/31.ics')) and os.path.isfile(os.path.join(M, 's/31.html')), '203: 31 files'
assert os.path.isfile(os.path.join(M, 'audio/index.json')), '203: audio/index.json missing'
PY
echo "203_law30_summary_31 OK"
exit 0
